-- Read-only. Save before application startup; do not automatically repair conflicts.
SELECT user_id,COUNT(*) active_count FROM nx_support_agent_user_assignment WHERE status='ACTIVE' AND is_deleted=0 GROUP BY user_id HAVING COUNT(*)>1;
SELECT x.id,x.user_id,x.agent_admin_id,a.status admin_status,p.enabled,p.seat_type FROM nx_support_agent_user_assignment x LEFT JOIN nx_admin a ON a.id=x.agent_admin_id LEFT JOIN nx_support_agent_profile p ON p.admin_id=a.id LEFT JOIN nx_user u ON u.id=x.user_id WHERE x.status='ACTIVE' AND x.is_deleted=0 AND (u.id IS NULL OR u.is_deleted<>0 OR a.id IS NULL OR a.status<>1 OR a.is_deleted<>0 OR p.admin_id IS NULL OR p.enabled<>1 OR p.is_deleted<>0 OR p.seat_type<>'DEDICATED' OR FIND_IN_SET('advisor',REPLACE(LOWER(p.service_types),' ',''))=0 OR NOT EXISTS(SELECT 1 FROM nx_admin_role_relation rr JOIN nx_admin_role r ON r.id=rr.role_id WHERE rr.admin_id=a.id AND rr.is_deleted=0 AND r.is_deleted=0 AND r.status=1 AND r.role_code='SUPPORT'));
SELECT DISTINCT c.user_id FROM nx_conversation c WHERE c.is_deleted=0 AND NOT EXISTS(SELECT 1 FROM nx_support_agent_user_assignment x WHERE x.user_id=c.user_id AND x.status='ACTIVE' AND x.is_deleted=0);
SELECT id,user_id,agent_admin_id,status,starts_at,ends_at FROM nx_support_agent_user_assignment ORDER BY id;
